#!/usr/bin/env node
import { copyFileSync, mkdirSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(__dirname, "..");
const tauriRoot = join(repoRoot, "src-tauri");
const hostName = "mori-browser-native-host";
const extension = process.platform === "win32" ? ".exe" : "";
const targetTriple = readRustHostTriple();
const cargoOutput = join(tauriRoot, "target", "release", `${hostName}${extension}`);
const bundledOutput = join(tauriRoot, "binaries", `${hostName}-${targetTriple}${extension}`);
const nsisGenerated = join(tauriRoot, "windows", "nsis", "browser-native-host.generated.nsh");

mkdirSync(dirname(bundledOutput), { recursive: true });
writeFileSync(bundledOutput, "");

run("cargo", [
  "build",
  "--release",
  "--locked",
  "--bin",
  hostName,
  "--manifest-path",
  join(tauriRoot, "Cargo.toml"),
]);

copyFileSync(cargoOutput, bundledOutput);
writeFileSync(nsisGenerated, buildNsisDefines(), "utf8");

console.log(`Prepared Browser native host sidecar: ${bundledOutput}`);
console.log(`Prepared Browser native host NSIS inputs: ${nsisGenerated}`);

function readRustHostTriple() {
  const result = spawnSync("rustc", ["-vV"], {
    cwd: repoRoot,
    encoding: "utf8",
    windowsHide: true,
  });
  if (result.status !== 0) {
    throw new Error(`rustc -vV failed.\n${result.stderr || result.stdout}`);
  }
  const match = /^host: (.+)$/m.exec(result.stdout);
  if (!match) throw new Error("rustc -vV did not report a host target triple.");
  return match[1];
}

function buildNsisDefines() {
  const chromeId = readExtensionId("MORI_BROWSER_CHROME_EXTENSION_ID");
  const edgeId = readExtensionId("MORI_BROWSER_EDGE_EXTENSION_ID");
  const allIds = Array.from(new Set([chromeId, edgeId].filter(Boolean)));
  return [
    "; Generated by scripts/prepare-browser-native-host-bundle.mjs.",
    `!define MORI_BROWSER_CHROME_EXTENSION_ID "${chromeId}"`,
    `!define MORI_BROWSER_EDGE_EXTENSION_ID "${edgeId}"`,
    `!define MORI_BROWSER_EXTENSION_IDS "${allIds.join(",")}"`,
    "",
  ].join("\n");
}

function readExtensionId(name) {
  const value = (process.env[name] || "").trim().toLowerCase();
  if (!value) return "";
  if (!/^[a-p]{32}$/.test(value)) {
    throw new Error(`${name} must be a 32-character Chromium extension id.`);
  }
  return value;
}

function run(command, args) {
  const result = spawnSync(command, args, {
    cwd: repoRoot,
    encoding: "utf8",
    stdio: "inherit",
    windowsHide: true,
  });
  if (result.status !== 0) {
    throw new Error(`${command} ${args.join(" ")} failed with exit code ${result.status}.`);
  }
}
